class Book:
    def __init__(self, title):
        self.title = title
        self.out = False
    def __str__(self):
        return self.title
class Library:
    def __init__(self):
        self.books = []
    def add(self, title):
        self.books.append(Book(title))
    def borrow(self, t):
        for b in self.books:
            if b.title == t:
                if not b.out:
                    b.out = True
                    return True
        return False
    def give_back(self, t):
        for b in self.books:
            if b.title == t and b.out:
                b.out = False
                return True
        return False
lib = Library()
lib.add("모비딕")
lib.add("데미안")
lib.add("어린왕자")
n = int(input())
for i in range(n):
    parts = input().split()
    if parts[0] == "대출":
        if lib.borrow(parts[1]):
            print("대출 성공")
        else:
            print("대출 실패")
    else:
        if lib.give_back(parts[1]):
            print("반납 성공")
        else:
            print("반납 실패")
count = 0
for b in lib.books:
    if b.out:
        count = count + 1
print("대출 중 " + str(count) + "권")
for b in lib.books:
    if b.out:
        print(b)

